</main>
<script>
const gradePeriods=<?= json_encode($gradeChartPeriods, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE) ?>;
let activeGradePeriod='current';
const gradePoints=()=>gradePeriods[activeGradePeriod].points;
const gradeLabels=points=>points.map((point,index)=>'Tugas '+(index+1));
const gradeMinimum=points=>Math.min(70,...points.map(point=>point.value));
function describeGradeChart(){
 const count=gradePoints().length;
 document.getElementById('grade-chart-description').textContent=count===0?'Belum ada penilaian pada periode ini':count===1?'Baru 1 tugas dinilai; tren perlu minimal 2 nilai':count+' penilaian terakhir pada periode ini';
 document.getElementById('nilaiChart').setAttribute('aria-label','Grafik perkembangan nilai per tugas: '+(count?gradePoints().map(point=>point.task+', nilai '+point.value).join('; '):'belum ada penilaian'));
}
const lastPoint={id:'lastPoint',afterDatasetsDraw(c){const d=c.data.datasets[0].data;let i=d.findLastIndex(v=>v!==null);if(i<0){const ctx=c.ctx,area=c.chartArea;ctx.save();ctx.fillStyle='#71817e';ctx.font='12px "Plus Jakarta Sans"';ctx.textAlign='center';ctx.fillText('Belum ada tugas yang dinilai',(area.left+area.right)/2,(area.top+area.bottom)/2);ctx.restore();return;}const p=c.getDatasetMeta(0).data[i];if(p.skip)return;const ctx=c.ctx;ctx.save();ctx.fillStyle='#006d66';ctx.beginPath();ctx.roundRect(p.x-30,p.y-33,60,23,7);ctx.fill();ctx.fillStyle='white';ctx.font='600 11px "Plus Jakarta Sans"';ctx.textAlign='center';ctx.fillText(Number(d[i]).toFixed(1),p.x,p.y-17);ctx.restore();}};
const line=new Chart(document.getElementById('nilaiChart'),{type:'line',data:{labels:gradeLabels(gradePoints()),datasets:[{data:gradePoints().map(point=>point.value),borderColor:'#006d66',borderWidth:3,backgroundColor:context=>{const g=context.chart.ctx.createLinearGradient(0,0,0,210);g.addColorStop(0,'#006d6640');g.addColorStop(1,'#006d6600');return g;},fill:true,tension:.4,pointBackgroundColor:'white',pointBorderWidth:3,pointRadius:4}]},plugins:[lastPoint],options:{responsive:true,maintainAspectRatio:false,layout:{padding:{top:24,right:30}},plugins:{legend:{display:false},tooltip:{callbacks:{title:items=>{const point=gradePoints()[items[0]?.dataIndex];return point?[point.task,point.subject]:'';},label:item=>'Nilai: '+Number(item.parsed.y).toFixed(1),afterLabel:item=>'Tanggal: '+gradePoints()[item.dataIndex].dateLabel}}},scales:{x:{offset:gradePoints().length===1,grid:{display:false},border:{display:false},ticks:{color:'#71817e',font:{size:10}}},y:{min:gradeMinimum(gradePoints()),max:100,ticks:{stepSize:10,color:'#71817e',font:{size:10}},border:{display:false},grid:{color:'#dbe7ff',tickLength:15}}}}});
describeGradeChart();
new Chart(document.getElementById('completionChart'),{type:'doughnut',data:{datasets:[{data:[<?= $subjectPercent ?>,<?= 100-$subjectPercent ?>],backgroundColor:['#006d66','#eff3ff'],borderWidth:0,borderRadius:10}]},options:{cutout:'80%',plugins:{legend:{display:false}},animation:false}});
document.querySelectorAll('[data-chart-period]').forEach(button=>button.addEventListener('click',()=>{
 activeGradePeriod=button.dataset.chartPeriod==='previous'?'previous':'current';
 document.querySelectorAll('[data-chart-period]').forEach(b=>b.classList.toggle('active',b===button));
 const points=gradePoints();
 line.data.labels=gradeLabels(points);
 line.data.datasets[0].data=points.map(point=>point.value);
 line.options.scales.x.offset=points.length===1;
 line.options.scales.y.min=gradeMinimum(points);
 describeGradeChart();
 line.update();
}));
</script>
<?php require __DIR__.'/../ui_end.php'; ?>
